    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '201: The "1-for-10" and "4-for-10" rules for respiratory acidosis are used to estimate the expected rise in:', '["pH", "Bicarbonate (HCO3)", "Sodium", "pCO2"]', 1, 'These rules help determine if the metabolic compensation for a primary respiratory disorder is appropriate.'),
    (v_topic_id, '202: A patient has pCO2 70 and HCO3 27. The pH is 7.21. Is this acute or chronic?', '["Acute (matches the 1-for-10 rule)", "Chronic (matches the 4-for-10 rule)", "Partially compensated", "Metabolic Alkalosis"]', 0, 'For pCO2 30 above normal (40 to 70), the HCO3 should rise by 3 (24 to 27). This is Acute Respiratory Acidosis.'),
    (v_topic_id, '203: A patient has pCO2 70 and HCO3 36. The pH is 7.33. Is this acute or chronic?', '["Acute", "Chronic (matches the 4-for-10 rule)", "Mixed disorder", "Respiratory Alkalosis"]', 1, 'For pCO2 30 above normal, the HCO3 should rise by ~12 (24 to 36). This matches Chronic Respiratory Acidosis.'),
    (v_topic_id, '204: Which of the following is the most sensitive way to detect "Mixed Acid-Base Disorders"?', '["Checking the pH only", "Systematically applying compensation formulas to every ABG", "Looking at the patient", "Guessing"]', 1, 'A mixed disorder is present if the measured values (pCO2 or HCO3) do not match the predicted values.'),
    (v_topic_id, '205: A "Triple Acid-Base Disorder" might be suspected in which clinical scenario?', '["Simple diarrhea", "A patient with Chronic COPD who presents with Sepsis and Vomiting", "A panic attack", "Opioid overdose"]', 1, 'This combination can create Respiratory Acidosis (COPD), HAGMA (Sepsis/Lactate), and Metabolic Alkalosis (Vomiting).'),
    (v_topic_id, '206: "Anion Gap" calculation is the first step in analyzing which primary disorder?', '["Metabolic Alkalosis", "Metabolic Acidosis (to find HAGMA)", "Respiratory Acidosis", "Respiratory Alkalosis"]', 1, 'The AG determines whether the acidosis is due to added acids (high AG) or loss of base (normal AG).'),
    (v_topic_id, '207: Which of the following is a "Triple Disorder" finding?', '["HAGMA + Metabolic Alkalosis + a Respiratory disorder", "Three types of Respiratory Acidosis", "Two types of Alkalosis", "None of the above"]', 0, 'This is a common "classic" boards question.'),
    (v_topic_id, '208: "Winter''s Formula" predicted pCO2 is 30. The actual pCO2 is 22. What is the interpretation?', '["Appropriate compensation", "Metabolic Acidosis + Respiratory Acidosis", "Metabolic Acidosis + Respiratory Alkalosis", "Normal"]', 2, 'The pCO2 is LOWER than expected, indicating an additional primary drive to hyperventilate.'),
    (v_topic_id, '209: "Winter''s Formula" predicted pCO2 is 30. The actual pCO2 is 40. What is the interpretation?', '["Appropriate compensation", "Metabolic Acidosis + Respiratory Acidosis", "Pure Respiratory Acidosis", "Normal"]', 1, 'The pCO2 is HIGHER than expected, indicating the patient is not ventilating enough (secondary respiratory acidosis).'),
    (v_topic_id, '210: Which electrolyte is most important to monitor when treating severe "Metabolic Acidosis" with bicarbonate?', '["Sodium", "Potassium (it will shift back into cells, potentially causing severe hypokalemia)", "Calcium", "Magnesium"]', 1, 'Correcting acidosis causes potassium to move intracellularly.'),
    (v_topic_id, '211: "Hypermagnesemia" can _____ the Anion Gap.', '["Increase", "Decrease (as an unmeasured cation)", "Not change", "Fix"]', 1, 'Like Calcium, Magnesium is a cation not included in the standard AG formula.'),
    (v_topic_id, '212: "Severe Hypophosphatemia" can cause which acid-base problem indirectly?', '["Respiratory Acidosis (due to diaphragmatic muscle weakness/respiratory failure)", "Metabolic Alkalosis", "NAGMA", "HAGMA"]', 0, 'Weakness of the respiratory muscles leads to hypoventilation.'),
    (v_topic_id, '213: "Obesity Hypoventilation Syndrome" (OHS) is also known as:', '["Pickwickian Syndrome", "Kussmaul Syndrome", "Bartter Syndrome", "Conn Syndrome"]', 0, 'It involves chronic hypercapnia in an obese patient that cannot be explained by other causes.'),
    (v_topic_id, '214: Which of the following is the most likely ABG in a patient with a "Massive Pulmonary Embolism"?', '["pH 7.30, pCO2 60 (Acidosis)", "pH 7.50, pCO2 25 (Respiratory Alkalosis)", "pH 7.40, pCO2 40", "pH 7.10, pCO2 80"]', 1, 'Tachypnea and hyperventilation are the most common responses to the hypoxia and distress of a PE.'),
    (v_topic_id, '215: In a patient with "Acute Asthma" exacerbation, a "Normal" pCO2 (e.g., 40 mmHg) is a sign of:', '["Improvement", "Impending respiratory failure (the patient is tiring and can no longer hyperventilate)", "Cure", "Normalization"]', 1, 'A tiring asthmatic will see their pCO2 rise from 25 to 35 to 40; this is a medical emergency.'),
    (v_topic_id, '216: "Central Neurogenic Hyperventilation" is a rare cause of respiratory alkalosis due to damage to the:', '["Lungs", "Brainstem", "Heart", "Kidneys"]', 1, 'It is sometimes seen in stroke or brain tumor patients.'),
    (v_topic_id, '217: "Cheyne-Stokes Respiration" is a pattern of breathing seen in:', '["Heart failure or Stroke (alternating apnea and hyperventilation)", "DKA", "Panic attacks", "Asthma"]', 0, 'It reflects a delayed response of the respiratory center to CO2 levels.'),
    (v_topic_id, '218: "Kussmaul Breathing" is most characteristic of:', '["Respiratory Alkalosis", "Severe Metabolic Acidosis (e.g., DKA)", "Heart failure", "Pneumonia"]', 1, 'Deep, rapid, gasping breaths intended to maximize CO2 elimination.'),
    (v_topic_id, '219: "Sleep Apnea" typically causes which chronic acid-base finding?', '["Chronic Respiratory Alkalosis", "Chronic Respiratory Acidosis with renal compensation", "Metabolic Alkalosis", "NAGMA"]', 1, 'Nocturnal hypoventilation leads to daytime CO2 retention and high bicarbonate.'),
    (v_topic_id, '220: "High Altitude Cerebral Edema" (HACE) and "High Altitude Pulmonary Edema" (HAPE) are risks of rapid ascent. The initial acid-base state at altitude is:', '["Respiratory Acidosis", "Respiratory Alkalosis", "Metabolic Acidosis", "Metabolic Alkalosis"]', 1, 'Driven by hypoxia-induced hyperventilation.'),
    (v_topic_id, '221: A patient with "Guillain-Barr\u00e9 Syndrome" develops a pCO2 of 55. This indicates:', '["Improvement", "Respiratory muscle failure requiring mechanical ventilation", "Metabolic compensation", "Panic"]', 1, 'Weakness of the "bellows" (muscles) leads to hypoventilation.'),
    (v_topic_id, '222: "Respiratory compensation" for metabolic acidosis is:', '["Always complete", "Incomplete (pH stays acidotic)", "Over-compensating", "Delayed by 48 hours"]', 1, 'Compensation brings the pH toward normal but never returns it to exactly 7.40.'),
    (v_topic_id, '223: "Metabolic compensation" for respiratory disorders takes _____ to fully develop.', '["Minutes", "Hours", "3 to 5 days", "Weeks"]', 2, 'The kidneys must adjust their rate of bicarbonate transport and ammonium production.'),
    (v_topic_id, '224: A patient with an ABG showing pH 7.20, pCO2 25, HCO3 10 and an AG of 25. Delta-Delta is:', '["1.0", "0.5", "2.0", "3.0"]', 0, '\u0394AG = 13 (25-12). \u0394HCO3 = 14 (24-10). Ratio \u2248 1. Interpretation: Pure HAGMA.'),
    (v_topic_id, '225: A patient with pH 7.10, pCO2 20, HCO3 6, and AG 30. Interpretation:', '["Pure HAGMA", "Mixed HAGMA and NAGMA", "HAGMA and Metabolic Alkalosis", "Respiratory Acidosis"]', 1, '\u0394AG = 18. \u0394HCO3 = 18. This matches a pure HAGMA. Wait, \u0394AG 18 + 6 = 24. This is pure HAGMA. Let me re-calculate: Ratio = 1.0.'),
    (v_topic_id, '226: "Urine Anion Gap" (UAG) of +30 mEq/L in a patient with NAGMA suggests:', '["Diarrhea", "Renal Tubular Acidosis (RTA)", "Lactic acidosis", "Ketoacidosis"]', 1, 'Positive UAG means the kidney is failing to excrete ammonium.'),
    (v_topic_id, '227: "Urine Anion Gap" (UAG) of -20 mEq/L in a patient with NAGMA suggests:', '["Type 1 RTA", "GI loss (Diarrhea) or Acetazolamide use", "Type 4 RTA", "Renal failure"]', 1, 'Negative UAG means the kidney is correctly excreting acid (as NH4Cl).'),
    (v_topic_id, '228: The "Anion Gap" of urine is primarily a surrogate for the concentration of:', '["Sodium", "Ammonium (NH4+)", "Glucose", "Urea"]', 1, 'We cannot directly measure urine ammonium easily, so we use U_Cl and the AG as a proxy.'),
    (v_topic_id, '229: In "Type 1 RTA," the primary defect is in the:', '["Proximal tubule", "Alpha-intercalated cells of the Distal Tubule", "Loop of Henle", "Glomerulus"]', 1, 'These cells fail to secrete H+ into the lumen.'),
    (v_topic_id, '230: In "Type 2 RTA," the primary defect is in the:', '["Proximal tubule (loss of carbonic anhydrase activity or transporters)", "Distal tubule", "Collecting duct", "Ureters"]', 0, 'This leads to "bicarbonaturia" until the serum level falls to a point where the proximal tubule can handle the load.'),
    (v_topic_id, '231: Which drug is a common cause of "Type 4 RTA" in diabetic patients?', '["ACE inhibitors or ARBs", "Penicillin", "Aspirin", "Metformin"]', 0, 'They inhibit the renin-angiotensin-aldosterone system, leading to hyperkalemia and acidosis.'),
    (v_topic_id, '232: "Hyperkalemia" itself can cause a metabolic acidosis by:', '["Interfering with ammonium (NH4+) production in the proximal tubule", "Causing hyperventilation", "Stopping the heart", "Bicarbonate loss"]', 0, 'This is a key mechanism in Type 4 RTA.'),
    (v_topic_id, '233: A "Normal" ABG in a patient who looks very sick should always be checked for:', '["Anion Gap", "Lactate", "Delta-delta", "All of the above"]', 3, 'A "Normal" pH of 7.40 can hide a severe HAGMA (AG 24) balanced by a severe Metabolic Alkalosis (HCO3 36).'),
    (v_topic_id, '234: "Carbonic Anhydrase" is an enzyme found in:', '["RBCs and Renal tubular cells", "Liver only", "Muscle only", "Heart only"]', 0, 'It catalyzes the reversible reaction between CO2/H2O and H2CO3.'),
    (v_topic_id, '235: A patient with "Severe Diarrhea" will have which ABG pattern?', '["HAGMA", "NAGMA with Hypokalemia", "Metabolic Alkalosis", "Respiratory Acidosis"]', 1, 'Diarrhea causes loss of HCO3 and K+.'),
    (v_topic_id, '236: A patient with "Severe Vomiting" will have which ABG pattern?', '["NAGMA", "Metabolic Alkalosis with Hypokalemia and Hypochloremia", "HAGMA", "Respiratory Alkalosis"]', 1, 'This is the "classic" vomiting profile.'),
    (v_topic_id, '237: Why does "Hypokalemia" occur in both vomiting AND diarrhea?', '["Potassium is in the stomach and stool", "In vomiting, volume depletion leads to secondary hyperaldosteronism, which wastes K+ in the urine", "Renal compensation", "Both A and B"]', 3, 'In vomiting, the renal loss of K+ is often greater than the gastric loss.'),
    (v_topic_id, '238: "MUDPILES" - The "S" stands for:', '["Sodium", "Salicylates", "Sugar", "Sepsis"]', 1, 'Aspirin overdose.'),
    (v_topic_id, '239: "MUDPILES" - The "L" stands for:', '["Lactic Acidosis", "Lithium", "Lead", "Liver failure"]', 0, 'The most common cause of HAGMA in the hospital.'),
    (v_topic_id, '240: "MUDPILES" - The "U" stands for:', '["Urea", "Uremia (Advanced Renal Failure)", "Urine", "Urticaria"]', 1, 'Retention of organic acids.'),
    (v_topic_id, '241: A patient with a pCO2 of 80 mmHg and pH of 7.10 is likely to be:', '["Awake and talking", "Somnolent or Comatose (CO2 Narcosis)", "Anxious and hyperventilating", "Doing exercise"]', 1, 'Severe hypercapnia has a sedative effect on the central nervous system.'),
    (v_topic_id, '242: "CO2 Narcosis" occurs when the pCO2 exceeds:', '["45 mmHg", "60 to 70 mmHg (variable depending on chronicity)", "100 mmHg", "50 mmHg"]', 1, 'Chronic retainers (COPD) tolerate much higher levels than healthy individuals.'),
    (v_topic_id, '243: The "Respiratory Center" is located in the:', '["Cerebral cortex", "Medulla Oblongata and Pons", "Cerebellum", "Hypothalamus"]', 1, 'It responds to pH and pCO2 signals from chemoreceptors.'),
    (v_topic_id, '244: "Central Chemoreceptors" respond primarily to changes in:', '["Arterial pO2", "pH of the Cerebrospinal Fluid (CSF)", "Sodium", "Glucose"]', 1, 'CO2 crosses the blood-brain barrier and becomes H+, stimulating the receptors.'),
    (v_topic_id, '245: "Peripheral Chemoreceptors" (Carotid and Aortic bodies) respond primarily to:', '["pH", "pO2 (hypoxia)", "pCO2", "Both A and B"]', 3, 'They are the primary drivers of ventilation in response to low oxygen.'),
    (v_topic_id, '246: "Carboxyhemoglobin" shifts the Oxygen-Hemoglobin Dissociation Curve to the:', '["Right", "Left", "Up", "Down"]', 1, 'This makes it harder for the remaining oxygen to be released to the tissues, worsening the hypoxia.'),
    (v_topic_id, '247: "Methemoglobinemia" is caused by iron in the hemoglobin being in the _____ state.', '["Ferrous (Fe2+)", "Ferric (Fe3+)", "Metallic", "Liquid"]', 1, 'Fe3+ cannot bind oxygen.'),
    (v_topic_id, '248: "Methylene Blue" is the treatment for Methemoglobinemia. It works by:', '["Adding oxygen", "Reducing the ferric iron (Fe3+) back to ferrous iron (Fe2+)", "Blocking the heart", "Excreting the drug"]', 1, 'It acts as an electron donor.'),
    (v_topic_id, '249: "Cyanide" does NOT affect the oxygen-hemoglobin curve; instead, it:', '["Blocks the lungs", "Inhibits cellular utilization of O2 (blocks the Mitochondria)", "Dissolves the blood", "Lowers the pH"]', 1, 'The venous pO2 in cyanide poisoning will be abnormally HIGH because the tissues can''t use the O2.'),
    (v_topic_id, '250: "Mixed Acid-Base Map" is a tool used to:', '["Find the patient''s house", "Graph the pH vs pCO2 to identify the primary and secondary disorders", "Calculate the Anion Gap", "Predict the weather"]', 1, 'It shows the expected ranges for simple and mixed disturbances.'),
    (v_topic_id, '251: A patient with HAGMA and an AG of 20. The HCO3 is 22. Interpretation?', '["Pure HAGMA", "HAGMA + Metabolic Alkalosis", "HAGMA + NAGMA", "Respiratory Acidosis"]', 1, '\u0394AG = 8 (20-12). If this were pure, the HCO3 should be 24 - 8 = 16. Since it is 22, an alkalosis is "pulling" it up.'),
    (v_topic_id, '252: "Anion Gap" calculation formula: Na - (Cl + HCO3). Why is Potassium often ignored?', '["It is too high", "Its concentration is small (4 mEq/L) and relatively constant, so it doesn''t change the diagnostic utility much", "It is an anion", "The lab doesn''t measure it"]', 1, 'Using Na + K - (Cl + HCO3) is also valid, but the "normal" range would be higher (12-16).'),
    (v_topic_id, '253: In the "Stewart" approach, a "Strong Ion" is one that is:', '["Acidic", "Completely dissociated at physiologic pH (e.g., Na, K, Cl, Lactate)", "Weak", "Protein-bound"]', 1, 'Their balance (SID) is a major determinant of pH.'),
    (v_topic_id, '254: "Independent Variables" in the Stewart approach include:', '["pH and HCO3", "pCO2, Strong Ion Difference (SID), and Total Weak Acid (A_tot)", "Sodium and Chloride", "None of the above"]', 1, 'pH and HCO3 are seen as dependent variables that change in response to these three.'),
    (v_topic_id, '255: A "Low pCO2" (< 35 mmHg) is the definition of:', '["Hypocapnia", "Hypercapnia", "Hypoxia", "Hyperoxia"]', 0, 'It usually indicates hyperventilation.'),
    (v_topic_id, '256: "Hypoventilation" causes pCO2 to:', '["Fall", "Rise", "Stay the same", "Become zero"]', 1, 'CO2 production exceeds CO2 elimination.'),
    (v_topic_id, '257: Which of the following is a symptom of "Acute Respiratory Alkalosis"?', '["Perioral numbness, carpopedal spasm, and lightheadedness", "Coma", "Heart failure", "Lethargy"]', 0, 'These are due to decreased ionized calcium and cerebral vasoconstriction.'),
    (v_topic_id, '258: "Cerebral blood flow" is highly sensitive to pCO2. "Hypocapnia" (Low pCO2) causes:', '["Cerebral vasodilation", "Cerebral vasoconstriction", "Stroke", "No change"]', 1, 'This is why hyperventilation is sometimes used acutely to lower intracranial pressure.'),
    (v_topic_id, '259: "Hypercapnia" (High pCO2) causes:', '["Cerebral vasoconstriction", "Cerebral vasodilation", "Brain shrinkage", "No change"]', 1, 'This can lead to increased intracranial pressure and "CO2 headaches."'),
    (v_topic_id, '260: "Anion Gap" calculation: Na 140, Cl 100, HCO3 20. AG is:', '["10", "20", "30", "40"]', 1, '140 - (100 + 20) = 20. This is an elevated AG.'),
    (v_topic_id, '261: "Osmolar Gap" calculation: Measured 310, Na 140, Gluc 180, BUN 28. Gap is:', '["0", "10", "20", "30"]', 1, 'Calculated = 2(140) + 180/18 + 28/2.8 = 280 + 10 + 10 = 300. Gap = 310 - 300 = 10.'),
    (v_topic_id, '262: "Bicarbonate" therapy in DKA should be considered only if the pH is less than:', '["7.30", "7.10", "6.90", "7.40"]', 2, 'Routine use of HCO3 in DKA is associated with complications and no clear benefit above pH 6.9.'),
    (v_topic_id, '263: "L-Lactate" is the product of _____ metabolism.', '["Anaerobic", "Aerobic", "Protein", "Fat"]', 0, 'It is produced when the rate of pyruvate production exceeds its entry into the Krebs cycle.'),
    (v_topic_id, '264: "Sepsis" causes Lactic Acidosis (HAGMA) primarily through:', '["Direct bacterial acid production", "Tissue hypoperfusion and mitochondrial dysfunction", "Diarrhea", "Vomiting"]', 1, 'This is the most common cause of high lactate in the ICU.'),
    (v_topic_id, '265: "Starvation" and "Ketosis" develop because the body shifts from using glucose to using _____ for energy.', '["Protein", "Fatty acids (producing ketones as a byproduct)", "Minerals", "Water"]', 1, 'The brain can use ketones as an alternative fuel source during prolonged fasting.'),
    (v_topic_id, '266: "Isopropyl Alcohol" (Rubbing alcohol) ingestion is classic for an elevated osmolar gap and:', '["Severe HAGMA", "Fruity breath (acetone) but NO AG acidosis", "Blindness", "Renal failure"]', 1, 'Acetone is the metabolite, which is a ketone but not an acid.'),
    (v_topic_id, '267: A patient with HAGMA and "Wood-alcohol" ingestion likely has:', '["Ethylene glycol toxicity", "Methanol toxicity", "Isopropyl alcohol toxicity", "Aspirin toxicity"]', 1, 'Methanol is also known as wood alcohol.'),
    (v_topic_id, '268: "Aspirin" (Salicylate) poisoning in ADULTS most commonly presents as:', '["Pure HAGMA", "Mixed Respiratory Alkalosis and HAGMA", "Pure Respiratory Acidosis", "NAGMA"]', 1, 'Adults almost always have the respiratory component; children may present with pure HAGMA.'),
    (v_topic_id, '269: "Winter''s Formula" predicted pCO2 is 18. Actual pCO2 is 18. This is:', '["Appropriate compensation", "Mixed disorder", "Failure to compensate", "Error"]', 0, 'The respiratory response is exactly what is expected for this level of acidosis.'),
    (v_topic_id, '270: The "Respiratory" compensation for "Metabolic Alkalosis" is to:', '["Breathe faster", "Breathe slower and shallower (Hypoventilate)", "Hold breath", "No change"]', 1, 'This retains CO2 to lower the pH.'),
    (v_topic_id, '271: Why is the respiratory compensation for metabolic alkalosis limited?', '["Because the patient gets tired", "Because hypoxia (low pO2) will eventually trigger the drive to breathe, even if the pH is high", "Because CO2 is toxic", "It isn''t limited"]', 1, 'Oxygen needs eventually override the acid-base needs.'),
    (v_topic_id, '272: "Contraction Alkalosis" is most commonly caused by which class of drugs?', '["Loop Diuretics (e.g., Furosemide)", "ACE inhibitors", "Beta-blockers", "Antibiotics"]', 0, 'They cause rapid loss of fluid and chloride.'),
    (v_topic_id, '273: "Chloride-Resistant" metabolic alkalosis with "Hypertension" suggests:', '["Vomiting", "Primary Hyperaldosteronism (Conn''s Syndrome) or Cushing''s Syndrome", "Diuretic use", "Diarrhea"]', 1, 'Excess mineralocorticoids cause salt retention (HTN) and H+/K+ loss.'),
    (v_topic_id, '274: "Chloride-Resistant" metabolic alkalosis with "Normal or Low" blood pressure suggests:', '["Cushing''s", "Bartter or Gitelman Syndrome", "Vomiting", "Conn''s"]', 1, 'These are salt-wasting genetic conditions.'),
    (v_topic_id, '275: "Renal Tubular Acidosis" (RTA) should be suspected in any patient with NAGMA and no history of:', '["Diarrhea", "Vomiting", "Aspirin use", "Smoking"]', 0, 'Diarrhea is the most common cause of NAGMA; RTA is the primary renal cause.'),
    (v_topic_id, '276: "Type 1 RTA" is also called "Distal RTA" because the defect is in the:', '["Glomerulus", "Distal convoluted tubule and collecting duct", "Proximal tubule", "Urethra"]', 1, 'The site of final urine acidification.'),
    (v_topic_id, '277: "Type 2 RTA" is also called "Proximal RTA" because the defect is in the:', '["Proximal convoluted tubule", "Loop of Henle", "Distal tubule", "Collecting duct"]', 0, 'The site of bulk bicarbonate reabsorption (85%).'),
    (v_topic_id, '278: "Hypokalemia" is the hallmark of which RTAs?', '["Types 1 and 2", "Type 4 only", "None", "All of them"]', 0, 'Types 1 and 2 involve K+ wasting; Type 4 involves K+ retention.'),
    (v_topic_id, '279: "Hyperkalemia" is the hallmark of which RTA?', '["Type 1", "Type 2", "Type 4", "Type 3"]', 2, 'It is the most common RTA seen in clinical practice, especially in diabetics.'),
    (v_topic_id, '280: "Fanconi Syndrome" includes which of the following findings?', '["Glucosuria, Phosphaturia, Aminoaciduria, and Proximal RTA", "Hypertension", "Hyperkalemia", "Kidney stones"]', 0, 'This is a global defect of the proximal tubule.'),
    (v_topic_id, '281: "Urine pH" is usually > 5.5 in which condition?', '["DKA", "Type 1 (Distal) RTA", "Type 2 RTA (eventually)", "Diarrhea"]', 1, 'The inability to acidify the urine is the defining feature of distal RTA.'),
    (v_topic_id, '282: In "Type 2 RTA," if the serum bicarbonate is very low (e.g., 12), the urine pH will be:', '["Acidic (< 5.5) because the distal tubule is still functional", "Alkaline (> 5.5)", "Normal", "Variable"]', 0, 'This is a key test to distinguish Type 1 from Type 2 RTA.'),
    (v_topic_id, '283: A "Bicarbonate Loading Test" is used to diagnose:', '["Type 1 RTA", "Type 2 RTA (HCO3 excretion will rise rapidly as the threshold is exceeded)", "Diabetes", "Heart failure"]', 1, 'It measures the fractional excretion of bicarbonate.'),
    (v_topic_id, '284: "Ammonium Chloride" (NH4Cl) loading test was historically used to diagnose:', '["Type 1 RTA (failure to drop urine pH despite acid load)", "Type 2 RTA", "Type 4 RTA", "Diarrhea"]', 0, 'It is rarely used now due to its unpleasantness and potential for harm.'),
    (v_topic_id, '285: "Acetazolamide" (Diamox) is a drug that INHIBITS:', '["Sodium channels", "Carbonic Anhydrase", "Potassium channels", "Aldosterone"]', 1, 'This prevents HCO3 reabsorption, causing a NAGMA.'),
    (v_topic_id, '286: "Acetazolamide" is useful for treating "Mountain Sickness" because it:', '["Lowers blood pressure", "Causes a metabolic acidosis, which stimulates the respiratory center to increase ventilation", "Adds oxygen to the blood", "Helps with sleep"]', 1, 'The metabolic acidosis "tricks" the body into breathing more.'),
    (v_topic_id, '287: "Primary Respiratory Acidosis" + "Primary Metabolic Acidosis" is a dangerous combination because:', '["The pH drops severely as there is no compensatory mechanism moving in the opposite direction", "The patient gets too much oxygen", "It is easy to treat", "The AG is always normal"]', 0, 'Example: A patient in shock (Lactic acidosis) who also has respiratory failure (CO2 retention).'),
    (v_topic_id, '288: "Primary Respiratory Alkalosis" + "Primary Metabolic Alkalosis" is a dangerous combination because:', '["The pH rises severely", "It causes pneumonia", "It causes heart attacks", "None of the above"]', 0, 'Example: A pregnant patient (Resp Alk) who is vomiting (Met Alk).'),
    (v_topic_id, '289: A patient has pH 7.40, pCO2 20, HCO3 12. Interpretation:', '["Normal ABG", "Mixed Respiratory Alkalosis and Metabolic Acidosis", "Pure Respiratory Alkalosis", "Pure Metabolic Acidosis"]', 1, 'Both disturbances are present and balancing each other perfectly regarding pH.'),
    (v_topic_id, '290: A patient has pH 7.40, pCO2 60, HCO3 36. Interpretation:', '["Normal ABG", "Mixed Respiratory Acidosis and Metabolic Alkalosis", "Pure Respiratory Acidosis", "Pure Metabolic Alkalosis"]', 1, 'Again, two primary disorders are balancing each other.'),
    (v_topic_id, '291: "Oxygen Content" of the blood depends on Hemoglobin level, SaO2, and:', '["pCO2", "Dissolved oxygen (0.003 * pO2)", "pH", "Sodium"]', 1, 'Dissolved O2 is usually a very small fraction of the total content.'),
    (v_topic_id, '292: The "Normal" A-a Gradient for a 20-year-old is approximately:', '["5 to 10 mmHg", "20 to 30 mmHg", "0 mmHg", "40 mmHg"]', 0, 'A small gradient exists even in health due to physiological shunt and V/Q mismatch.'),
    (v_topic_id, '293: The "Normal" A-a Gradient for an 80-year-old is approximately:', '["5 to 10 mmHg", "20 to 25 mmHg", "50 mmHg", "0 mmHg"]', 1, 'Gradient increases with age as the lung becomes less efficient.'),
    (v_topic_id, '294: "V/Q Mismatch" is the most common cause of hypoxia and is seen in:', '["Pneumonia, Pulmonary Edema, and COPD", "Pure hypoventilation", "High altitude", "Cyanide poisoning"]', 0, 'Areas of the lung are perfused but not well ventilated (or vice versa).'),
    (v_topic_id, '295: "Right-to-Left Shunt" causes hypoxia that is unique because it:', '["Does not respond to supplemental oxygen", "Responds very well to oxygen", "Has a normal A-a gradient", "Is only seen in the elderly"]', 0, 'Blood is completely bypassing the alveoli; 100% O2 cannot reach it.'),
    (v_topic_id, '296: "Diffusion Limitation" is a cause of hypoxia seen in:', '["Asthma", "Interstitial Lung Disease / Fibrosis (thickened alveolar walls)", "Pulmonary Embolism", "Opioid overdose"]', 1, 'The gas cannot cross the thickened membrane quickly enough, especially during exercise.'),
